[Form]
public class GUPPricingAttributeGroup extends FormRun  implements OfficeIMenuCustomizer
{
    private GUPPricingAttributeTmp priceAttributes;

    private GUPPricingAttributeGroupType groupType;
    private GUPPricingAttributeSourceLevel sourceLevel;

    private Query productPreviewQuery;
    private Query custPreviewQuery;

    public GUPPricingAttributeLink lastAddedPricingAttributeLink;

}

public void customizeMenuOptions(OfficeMenuOptions _menuOptions)
{
    ListIterator dataEntityIterator = new ListIterator(_menuOptions.dataEntityOptions());

    while (dataEntityIterator.more())
    {
        dataEntityIterator.delete();
    }

    switch (element.args().menuItemName())
    {
        case menuItemDisplayStr(GUPPricingAttributeGroupCust):
            _menuOptions.dataEntityOptions()
                .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPCustomerPricingAttributeGroupEntity)));
            _menuOptions.dataEntityOptions()
                .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPCustomerPricingAttributeLinkEntity)));
            break;

        case menuItemDisplayStr(GUPPricingAttributeGroupProduct):
            _menuOptions.dataEntityOptions()
                .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPProductPricingAttributeGroupEntity)));
            _menuOptions.dataEntityOptions()
                .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPProductPricingAttributeLinkEntity)));
            break;
        default:
            _menuOptions.dataEntityOptions()
                .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPPricingAttributeGroupEntity)));
            _menuOptions.dataEntityOptions()
                .addEnd(OfficeMenuDataEntityOptions::construct(tableStr(GUPPricingAttributeLinkEntity)));
    }

}

public GUPPricingAttributeLink parmLastAddedPricingAttributeLink(GUPPricingAttributeLink _pricingAttributeLink)
{
    lastAddedPricingAttributeLink = _pricingAttributeLink;
    return _pricingAttributeLink;
}

private void initPriceAttributeTmp()
{
    select firstonly RecId from priceAttributes;
    if (!priceAttributes.RecId)
    {
        List attributes = GUPPricingAttributeRepository::getAllPricingAttributes();
        Enumerator enum = attributes.getEnumerator();

        ttsbegin;

        GUPIPricingAttribute pricingAttr;
        GUPPricingAttributeLink link;
        GUPPricingAttributeSourceDiscoveryAttribute discoveryAttributeAsObject;
        int cnt = 1;

        while (enum.moveNext())
        {
            pricingAttr = enum.current();
            link = GUPPricingAttributeRepository::toPriceAttributeLink(pricingAttr);
            priceAttributes.AttributeName = link.AttributeName;
            priceAttributes.PriceAttributeClassId = link.PriceAttributeClassId;
            priceAttributes.TypeName = link.TypeName;
            priceAttributes.ProviderClassId = link.AttributeProviderClassId;
            priceAttributes.Id = cnt;

            discoveryAttributeAsObject =
                GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
                    pricingAttr,
                    attributeStr(GUPPricingAttributeSourceDiscoveryAttribute));

            priceAttributes.Level = discoveryAttributeAsObject.parmLevel();
            priceAttributes.Source = discoveryAttributeAsObject.parmSource();
            priceAttributes.PriceAttributeClassName = classId2Name(link.PriceAttributeClassId);
            priceAttributes.insert();
            cnt++;
        }
        ttscommit;
    }
}

public void init()
{
    switch (element.args().menuItemName())
    {
        case menuItemDisplayStr(GUPPricingAttributeGroupCust):
            groupType = GUPPricingAttributeGroupType::Customer;               
            break;

        case menuItemDisplayStr(GUPPricingAttributeGroupProduct):
            groupType = GUPPricingAttributeGroupType::Product;
            break;
        default:
            groupType = GUPPricingAttributeGroupType::General;
    }

    super();

    GUPPricingAttributeRepository::clearCache();
    element.initPriceAttributeTmp();
    element.setControlsVisible();
    element.setCaption();

}

private void setCaption()
{
    switch (groupType)
    {
        case GUPPricingAttributeGroupType::Customer:
            this.design().caption("@GlobalUnifiedPricing:GUPCustomerAttributeGroups");
            break;

        case GUPPricingAttributeGroupType::Product:
            this.design().caption("@GlobalUnifiedPricing:GUPProductAttributeGroups");
            break;

        default:
            break;
    }
}

/// <summary>
/// Set controls visibility
/// </summary>
private void setControlsVisible()
{
    switch (groupType)
    {
        case GUPPricingAttributeGroupType::Customer:
            PreviewCustTabPage.visible(true);
            PreviewProductTabPage.visible(false);

            GUPPricingAttributeGroup_ds.object(fieldNum(GUPPricingAttributeGroup, SourceLevel)).enabled(false);
            break;

        case GUPPricingAttributeGroupType::Product:
            PreviewCustTabPage.visible(false);
            PreviewProductTabPage.visible(true);

            GUPPricingAttributeGroup_ds.object(fieldNum(GUPPricingAttributeGroup, SourceLevel)).enabled(false);
            break;

        default:
            PriceAttribute_Value.visible(false);
            Checkbox_AppendValueOnLookup.visible(false);
            PreviewCustTabPage.visible(false);
            PreviewProductTabPage.visible(false);
    }
}

/// <summary>
/// Expand product variants
/// </summary>
/// <param name = "_qbdsParent">Parent data source</param>
/// <param name = "_joinMode">Join mode</param>
public void addAllProductVariants(QueryBuildDataSource _qbdsParent, JoinMode _joinMode = JoinMode::InnerJoin)
{
    QueryBuildDataSource qbdsInventDimCombination = _qbdsParent.addDataSource(tableNum(InventDimCombination));

    qbdsInventDimCombination.addLink(fieldNum(InventTable, ItemId), fieldNum(InventDimCombination, ItemId));
    qbdsInventDimCombination.joinMode(_joinMode);
}

/// <summary>
/// Link line type table to Customer/Item/Product variant data source
/// </summary>
/// <param name = "_qbdsParent">Parent Customer/Item/Product data source</param>
private void addLineTypeLink(QueryBuildDataSource _qbdsParent)
{
    QueryBuildDataSource qbdsLineState = _qbdsParent.addDataSource(tableNum(GUPPricingAttributeLineState));
    qbdsLineState.relations(true);
    qbdsLineState.joinMode(JoinMode::OuterJoin);

    qbdsLineState.addRange(fieldNum(GUPPricingAttributeLineState, ParentTableId)).value(queryValue(GUPPricingAttributeGroup.TableId));
    qbdsLineState.addRange(fieldNum(GUPPricingAttributeLineState, ParentRecId)).value(queryValue(GUPPricingAttributeGroup.RecId));
}

public void toggleAllVariantsBtns()
{   
    GUPPricingAttributeGroup.ProductAllVariants = GUPPricingAttributeGroup.ProductAllVariants == NoYes::Yes ? NoYes::No : NoYes::Yes;
    GUPPricingAttributeGroup.write();
    AllVariantsBtn.visible(GUPPricingAttributeGroup.ProductAllVariants == NoYes::No);
    ProductMasterBtn.visible(GUPPricingAttributeGroup.ProductAllVariants == NoYes::Yes);
    InventDimCombination_DistinctProductVariant.visible(GUPPricingAttributeGroup.ProductAllVariants == NoYes::Yes);

    GUPPricingAttributeLineState::clearLineState(GUPPricingAttributeGroup.TableId, GUPPricingAttributeGroup.RecId);

    element.researchPreviewQuery();
}

/// <summary>
/// Filter preview query according to slected pricing attributes
/// </summary>
private void researchPreviewQuery()
{
    switch (groupType)
    {
        case GUPPricingAttributeGroupType::Customer:
            custPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingGroup(GUPPricingAttributeGroup).build();
            element.addLineTypeLink(custPreviewQuery.dataSourceTable(tableNum(CustTable)));

            CustTable_ds.executeQuery();
            break;

        case GUPPricingAttributeGroupType::Product:
            if (GUPPricingAttributeGroup.ProductAllVariants == NoYes::Yes)
            {
                productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingGroup(GUPPricingAttributeGroup, true).addProductVariants().build();
                element.addLineTypeLink(productPreviewQuery.dataSourceTable(tableNum(InventDimCombination)));
            }
            else
            {
                productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingGroup(GUPPricingAttributeGroup).build();

                element.addAllProductVariants(productPreviewQuery.dataSourceTable(tableNum(InventTable)), JoinMode::OuterJoin);
                element.addLineTypeLink(productPreviewQuery.dataSourceTable(tableNum(InventTable)));                    
            }

            InventTable_ds.executeQuery();
            break;
    }
}

/// <summary>
/// Initialize default fields values
/// </summary>
public void initValue()
{
    super();

    GUPPricingAttributeGroup.GroupType = groupType;

    switch (groupType)
    {
        case GUPPricingAttributeGroupType::Customer:
            GUPPricingAttributeGroup.SourceLevel = GUPPricingAttributeSourceLevel::Header;
            break;

        case GUPPricingAttributeGroupType::Product:
            GUPPricingAttributeGroup.SourceLevel = GUPPricingAttributeSourceLevel::Line;
            break;

        default:
            GUPPricingAttributeGroup.SourceLevel = -1;
    }

}

/// <summary>
/// Init data source ranges
/// </summary>
public void init()
{
    QueryBuildRange qbrGroupType;

    super();

    qbrGroupType = SysQuery::findOrCreateRange(GUPPricingAttributeGroup_ds.queryBuildDataSource(), fieldNum(GUPPricingAttributeGroup, GroupType));
    qbrGroupType.value(queryValue(groupType));
}

public int active()
{
    int ret;

    ret = super(); 

    AllVariantsBtn.visible(GUPPricingAttributeGroup.ProductAllVariants == NoYes::No);
    ProductMasterBtn.visible(GUPPricingAttributeGroup.ProductAllVariants == NoYes::Yes);
    InventDimCombination_DistinctProductVariant.visible(GUPPricingAttributeGroup.ProductAllVariants == NoYes::Yes);

    if (GUPPricingAttributeGroup.RecId)
    {
        element.researchPreviewQuery();
    }

    NewLine.enabled(GUPPricingAttributeGroup.RecId);

    return ret;
}

public void delete()
{
    super();

    NewLine.enabled(GUPPricingAttributeGroup.RecId);
}

public edit Name editAttributeName(boolean _set, GUPPricingAttributeLink _link, Name _name)
{
    if (_set)
    {
        var rec = str2Int(_name);
        select firstonly * from priceAttributes where priceAttributes.Id == rec;

        GUPIPricingAttribute priceAttribute = GUPPricingAttributeRepository::priceAttribute(
            priceAttributes.PriceAttributeClassId, priceAttributes.ProviderClassId, priceAttributes.AttributeName, priceAttributes.TypeName);

        _link.PriceAttributeClassId = classIdGet(priceAttribute);
        _link.AttributeName = priceAttributes.AttributeName;
        _link.AttributeProviderClassId = priceAttributes.ProviderClassId;
        _link.TypeName = priceAttributes.TypeName;
        _link.Priority = this.getHighestPriority();
    }

    return _link.AttributeName;
}

public edit Name editAttributeDefaultValue(boolean _set, GUPPricingAttributeLink _link, Name _name)
{
    // When change value.
    if (_set)
    {                
        _link.DefaultValue = GUPPricingAttributeConditionValueHelper::editConditionValue(_name, _link.DefaultValue, Checkbox_AppendValueOnLookup.checked(), _link);
        _link.write();
    }
    return GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(_link.AttributeName, _link.DefaultValue, _link);
}

public display str displayAttributeType(GUPPricingAttributeLink _link)
{
    str typeName;

    if (_link.AttributeName)
    {
        typeName = enum2Symbol(enumNum(AttributeDataType), _link.pricingAttribute().getDataType());
    }

    return typeName;
}

public display str displayAttributePriority(GUPPricingAttributeLink _link)
{
    str priority;

    if (_link.Priority)
    {
        priority = int2Str(_link.Priority);
    }

    return priority;
}

public void write()
{
    super();

    element.researchPreviewQuery();
}

public int getHighestPriority()
{
    GUPPricingAttributeLink link;
    select firstonly Priority from link order by Priority desc
        where link.PriceAttributeGroupName == GUPPricingAttributeLink.PriceAttributeGroupName;
    return link.Priority + 1;
}

