public void clicked()
{
    super();
    element.initPriceAttributeTmp();
    xArgs args = new Args();

    Form _form = new Form(formStr(GUPViewAllPricingAttributes));
    args.object(_form);
    args.record(element.priceAttributes);

    FormRun attributeGroupTreeFromRun = ClassFactory.formRunClass(args);

    attributeGroupTreeFromRun.init();
    attributeGroupTreeFromRun.run();
    attributeGroupTreeFromRun.wait();
}

public void clicked()
{
    super();

    xArgs args = new Args();

    Form addPriceAttributeDialog = new Form(formStr(GUPAddPriceAttribute));

    args.object(addPriceAttributeDialog);
    args.caller(element);

    args.record(GUPPricingAttributeGroup);  

    FormRun addPriceAttributeDialogFromRun = ClassFactory.formRunClass(args);
    addPriceAttributeDialogFromRun.init();
    addPriceAttributeDialogFromRun.run();
    addPriceAttributeDialogFromRun.wait();

    GUPPricingAttributeGroup_ds.reread();
    GUPPricingAttributeLink_ds.research(true);
    GUPPricingAttributeLink_ds.refresh();

    if(addPriceAttributeDialogFromRun)
    {
        if (addPriceAttributeDialogFromRun.dataSource(tableStr(GUPPricingAttributeLink)))
        {
            FormDataSource formDS = addPriceAttributeDialogFromRun.dataSource(tableStr(GUPPricingAttributeTmp));                    
            GUPPricingAttributeLink_ds.positionToRecord(GUPPricingAttributeLink::find(lastAddedPricingAttributeLink.RecId));
        }
    }

}

void clicked()
{
    super();

    if (GUPPricingAttributeGroup::isPricingAttributeGroupUsed(GUPPricingAttributeLink.PriceAttributeGroupName))
    {
        warning("@GlobalUnifiedPricing:GUPPricingAttributeGroupIsUsed");
        return;
    }

    GUPPricingAttributeLink pricingAttributeLink;
    pricingAttributeLink = GUPPricingAttributeLink::find(GUPPricingAttributeLink.RecId, true);

    pricingAttributeLink.moveUp();
    GUPPricingAttributeLink_ds.research(false);
    GUPPricingAttributeLink_ds.positionToRecord(pricingAttributeLink);
}

void clicked()
{
