/// <summary>
/// Exclude record from pricing query
/// </summary>
public void clicked()
{
    GUPPricingAttributeLineType exclType = GUPPricingAttributeLineStateCust ? GUPPricingAttributeLineType::Include : GUPPricingAttributeLineType::Exclude;
    CustTable custTableLocal;

    super();

    for(custTableLocal = CustTable_ds.getFirst(true) ? CustTable_ds.getFirst(true) : CustTable_ds.cursor(); 
        custTableLocal; 
        custTableLocal = CustTable_ds.getNext())
    {
        GUPPricingAttributeGroup.inclExclRelLine(exclType, custTableLocal.TableId, custTableLocal.RecId);
    }

    CustTable_ds.research(true);
    CustTable_ds.refresh();
}

/// <summary>
/// Exclude record from pricing query
/// </summary>
public void clicked()
{            
    super();

    GUPPricingAttributeLineType exclType = GUPPricingAttributeLineStateProduct ? GUPPricingAttributeLineType::Include : GUPPricingAttributeLineType::Exclude;

    if (GUPPricingAttributeGroup.ProductAllVariants == NoYes::Yes)
    {
        InventDimCombination inventDimCombinationLocal;

        for (   inventDimCombinationLocal = InventDimCombination_ds.getFirst(true) ? InventDimCombination_ds.getFirst(true) : InventDimCombination_ds.cursor();
                inventDimCombinationLocal;
                inventDimCombinationLocal = InventDimCombination_ds.getNext())
        {
            GUPPricingAttributeGroup.inclExclRelLine(exclType, inventDimCombinationLocal.TableId, inventDimCombinationLocal.RecId);
        }
    }
    else
    {
        InventTable inventTableLocal;

        for (   inventTableLocal = InventTable_ds.getFirst(true) ? InventTable_ds.getFirst(true) : InventTable_ds.cursor();
                inventTableLocal;
                inventTableLocal = InventTable_ds.getNext())
        {
            GUPPricingAttributeGroup.inclExclRelLine(exclType, inventTableLocal.TableId, inventTableLocal.RecId);
        }
    }

    InventTable_ds.research(true);
    InventTable_ds.refresh();
}

